n  color: var(--text-secondary);\n  padding: 0.4rem 0.5rem;\n  cursor: pointer;\n  border-radius: 0.35rem;\n  transition: all 0.3s ease;\n  text-align: center;\n\n  &:hover {\n    color: var(--text-primary);\n    background: rgba(255, 138, 128, 0.08);\n  }\n\n  &.active {\n    color: var(--user-color-primary);\n    background: var(--bg-main);\n    box-shadow: 0 1px 4px rgba(255, 138, 128, 0.15);\n  }\n}\n\n.profile-content {\n  display: none;\n  flex: 1;\n  overflow-y: auto;\n\n  &.active {\n    display: block;\n  }\n}\n\n.events-list {\n  display: flex;\n  flex-direction: column;\n  gap: 0.5rem;\n}\n\n.event-entry {\n  background: var(--bg-panel);\n  border: 1px solid var(--border-color);\n  border-radius: 0.5rem;\n  padding: 0.625rem 0.875rem;\n  animation: slideIn 0.3s ease-out;\n\n  &:hover {\n    border-color: var(--user-color-primary);\n  }\n}\n\n.event-time {\n  font-family: var(--font-title);\n  font-size: 0.75rem;\n  color: var(--user-color-primary);\n  margin-bottom: 0.2rem;\n}\n\n.event-location {\n  font-family: var(--font-serif);\n  font-size: 0.7rem;\n  color: var(--text-secondary);\n  margin-bottom: 0.3rem;\n}\n\n.event-content {\n  font-family: var(--font-serif);\n  font-size: 0.8rem;\n  color: var(--text-primary);\n  line-height: 1.4;\n}\n\n.classmates-cards-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(5rem, 1fr));\n  gap: 0.5rem;\n  padding: 0.25rem;\n}\n\n.classmate-card {\n  background: var(--bg-panel);\n  border: 1px solid var(--border-color);\n  border-radius: 0.5rem;\n  padding: 0.5rem;\n  cursor: pointer;\n  transition: all 0.3s ease;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  text-align: center;\n\n  &:hover {\n    border-color: var(--accent-color);\n    transform: translateY(-2px);\n    box-shadow: 0 4px 12px rgba(255, 138, 128, 0.15);\n  }\n}\n\n.classmate-avatar {\n  width: 2rem;\n  height: 2rem;\n  border-radius: 50%;\n  background: linear-gradient(135deg, var(--user-color-primary), var(--user-color-secondary));\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-family: var(--font-title);\n  font-size: 0.9rem;\n  color: #fff;\n  margin-bottom: 0.35rem;\n  box-shadow: 0 2px 6px rgba(255, 138, 128, 0.2);\n}\n\n.classmate-name {\n  font-family: var(--font-title);\n  font-size: 0.75rem;\n  color: var(--text-primary);\n  margin-bottom: 0.2rem;\n}\n\n.classmate-relation {\n  font-family: var(--font-serif);\n  font-size: 0.65rem;\n  padding: 0.1rem 0.3rem;\n  border-radius: 0.2rem;\n  background: rgba(255, 183, 178, 0.15);\n  color: var(--text-secondary);\n}\n\n.classmate-relation.close {\n  color: #81c784;\n}\n\n.classmate-relation.affection {\n  color: #f48fb1;\n}\n\n.classmate-relation.enemy {\n  color: #ef5350;\n}\n\n.no-events,\n.classmates-empty {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  height: 100%;\n  color: var(--text-secondary);\n  font-family: var(--font-title);\n  font-size: 0.85rem;\n}\n\n@keyframes slideIn {\n  from {\n    opacity: 0;\n    transform: translateY(-10px);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n.add-character-form {\n  padding: 0.5rem;\n  display: flex;\n  flex-direction: column;\n  gap: 0.75rem;\n}\n\n.form-group {\n  display: flex;\n  flex-direction: column;\n  gap: 0.3rem;\n\n  label {\n    font-family: var(--font-title);\n    font-size: 0.75rem;\n    color: var(--text-secondary);\n  }\n\n  input,\n  select {\n    background: var(--bg-panel);\n    border: 1px solid var(--border-color);\n    border-radius: 0.35rem;\n    padding: 0.5rem;\n    font-family: var(--font-serif);\n    font-size: 0.8rem;\n    color: var(--text-primary);\n    outline: none;\n    transition: border-color 0.3s ease;\n\n    &:focus {\n      border-color: var(--user-color-primary);\n    }\n\n    &::placeholder {\n      color: var(--text-secondary);\n      opacity: 0.6;\n    }\n  }\n\n  select {\n    cursor: pointer;\n  }\n}\n\n.add-btn {\n  margin-top: 0.5rem;\n  background: linear-gradient(135deg, var(--user-color-primary), var(--user-color-secondary));\n  border: none;\n  border-radius: 0.35rem;\n  padding: 0.6rem 1rem;\n  font-family: var(--font-title);\n  font-size: 0.8rem;\n  color: #fff;\n  cursor: pointer;\n  transition: all 0.3s ease;\n\n  &:hover {\n    transform: translateY(-2px);\n    box-shadow: 0 4px 12px rgba(255, 138, 128, 0.3);\n  }\n\n  &:active {\n    transform: translateY(0);\n  }\n}\n"],"sourceRoot":""}]);
