x;\n  justify-content: space-between;\n  margin-top: 0.4rem;\n  background: var(--bg-panel);\n  border-radius: 0.75rem 0.75rem 0 0;\n  padding: 0.25rem;\n  border-bottom: 1px solid var(--border-color);\n}\n\n.tab-button {\n  flex: 1;\n  font-family: var(--font-title);\n  font-size: 0.85rem;\n  color: var(--text-secondary);\n  letter-spacing: 1px;\n  padding: 0.6rem 0.4rem;\n  cursor: pointer;\n  background-color: transparent;\n  border: 1px solid transparent;\n  border-radius: 0.5rem;\n  transition: all 0.3s ease;\n  text-align: center;\n  position: relative;\n  overflow: hidden;\n\n  &:hover {\n    color: var(--text-primary);\n    background-color: rgba(255, 138, 128, 0.08);\n  }\n\n  &.active {\n    color: var(--text-title);\n    background-color: var(--bg-main);\n    box-shadow: 0 2px 8px rgba(255, 138, 128, 0.15);\n\n    &::after {\n      content: '';\n      position: absolute;\n      bottom: 0;\n      left: 50%;\n      transform: translateX(-50%);\n      width: 60%;\n      height: 0.2rem;\n      background: linear-gradient(90deg, var(--user-color-primary), var(--user-color-secondary));\n      border-radius: 0.25rem 0.25rem 0 0;\n    }\n  }\n}\n\n.page-container {\n  display: none;\n  border-radius: 0 0 0.75rem 0.75rem;\n  padding: 0.5rem;\n  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);\n  animation: fadeIn 0.5s ease-out;\n  max-height: 20rem;\n  height: 20rem;\n  overflow-y: auto;\n}\n\n.page-container.active {\n  display: block;\n}\n\n::-webkit-scrollbar {\n  width: 0.4rem;\n}\n\n::-webkit-scrollbar-track {\n  background: rgba(255, 138, 128, 0.05);\n  border-radius: 0.2rem;\n}\n\n::-webkit-scrollbar-thumb {\n  background: rgba(255, 138, 128, 0.3);\n  border-radius: 0.2rem;\n\n  &:hover {\n    background: var(--user-color-primary);\n  }\n}\n\n@media (max-width: 768px) {\n  .info-group {\n    gap: 0.5rem;\n  }\n  .info-item {\n    min-width: 100%;\n    flex: 1;\n  }\n  .info-label {\n    font-size: 0.7rem;\n    margin-bottom: 0.15rem;\n  }\n  .info-value {\n    font-size: 0.8rem;\n    line-height: 1.3;\n  }\n  .character-detail-info {\n    padding: 0.5rem;\n  }\n  .martial-arts-container {\n    gap: 0.35rem;\n  }\n  .martial-art-item {\n    padding: 0.4rem 0.6rem;\n  }\n  .martial-art-name {\n    font-size: 0.75rem;\n  }\n}\n"],"sourceRoot":""}]);
